files.content:
html {
  block-size: 100%;
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  block-size: 100%;
}

body::after {
  content: '';
  position: absolute;
  inset: 60% 0 0;
  z-index: -1;
  border-block-start: 1px solid;
  background-color: #80d994;
}

.tv {
  position: relative;
  inline-size: 450px;
}

/* цвет экрана */

.tv::before {
  content: '';
  position: absolute;
  inset: 150px 0 20px;
  z-index: 0;
  background-color: #000;
}

svg {
  position: relative;
  z-index: 1;
}

.tv-button {
  position: absolute;
  z-index: 2;
  border: 1px solid #000;
  border-radius: 50%;
  box-shadow: 5px 5px 0 0 rgb(0 0 0 / 0.25);
  background-color: #ffc802;
  cursor: pointer;
  inset-inline-end: 32px;
  inset-block-end: 56px;
  inline-size: 50px;
  block-size: 50px;
}

.visually-hidden {
  position: absolute;
  overflow: hidden;
  clip: rect(0 0 0 0);
  inline-size: 1px;
  block-size: 1px;
  clip-path: inset(50%);
  white-space: nowrap;
}

.tv-button:hover,
.tv-button:focus {
  outline: none;
  box-shadow: 0 0 0 2px rgba(70 42 68 / 1), 0 0 0 8px rgba(255 230 160 / 1);
}
